const listActivityMarkers = `-- name: ListActivityMarkers :many
SELECT
    t.id AS task_id,
    COALESCE((
        SELECT j.stage FROM jobs j
        WHERE j.task_id = t.id
        ORDER BY j.started_at DESC, j.id DESC
        LIMIT 1
    ), '')::text AS latest_stage,
    COALESCE((
        SELECT e.at FROM events e
        WHERE e.task_id = t.id
        ORDER BY e.id DESC
        LIMIT 1
    ), t.created_at)::timestamptz AS last_event_at
FROM tasks t
WHERE t.workspace_id = $1
ORDER BY t.created_at, t.id
`

type ListActivityMarkersRow struct {
	TaskID      string             `json:"task_id"`
	LatestStage string             `json:"latest_stage"`
	LastEventAt pgtype.Timestamptz `json:"last_event_at"`
}

func (q *Queries) ListActivityMarkers(ctx context.Context, workspaceID string) ([]ListActivityMarkersRow, error) {
	rows, err := q.db.Query(ctx, listActivityMarkers, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListActivityMarkersRow{}
	for rows.Next() {
		var i ListActivityMarkersRow
		if err := rows.Scan(&i.TaskID, &i.LatestStage, &i.LastEventAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

